// Generated by tools/generate-confirm-sheet-plan.ts. Run it after changing CSV rules.
import type { Order, OrderSource, Product, StoreSettings, PaymentMethod } from '../types';
import { canonicalJson, type ConfirmCsvEntry } from './confirmCsvSave';
import { findProductSelection, normalizedProductType, buildOrderItemSnapshot } from './productVariants';

export function planConfirmSheetDecisions(matrix:string[][],orders:Order[],products:Product[],settings:StoreSettings,packingBatchId:string,at:string) {
  const source:OrderSource|undefined=undefined;
  const paymentMode:'normal'|'full_paid'|'advance_50'='normal' as any;
  const getMultiBuyDiscountRate = (qty: number) => {
    if (settings.free_delivery_enabled === true || settings.multi_buy_discount_enabled === false || qty <= 1) return 0;
    const t1Min = Math.max(2, Number(settings.multi_buy_tier1_min ?? 2));
    const t1Max = Math.max(t1Min, Number(settings.multi_buy_tier1_max ?? 3));
    const t1Rate = Math.max(0, Math.min(100, Number(settings.multi_buy_tier1_rate ?? 5)));
    const t2Min = Math.max(t1Max + 1, Number(settings.multi_buy_tier2_min ?? 4));
    const t2Max = Math.max(t2Min, Number(settings.multi_buy_tier2_max ?? 5));
    const t2Rate = Math.max(0, Math.min(100, Number(settings.multi_buy_tier2_rate ?? 7.5)));
    const t3Min = Math.max(t2Max + 1, Number(settings.multi_buy_tier3_min ?? 6));
    const t3Rate = Math.max(0, Math.min(100, Number(settings.multi_buy_tier3_rate ?? 10)));
    if (qty >= t1Min && qty <= t1Max) return t1Rate;
    if (qty >= t2Min && qty <= t2Max) return t2Rate;
    if (qty >= t3Min) return t3Rate;
    return 0;
  };


    const errors:string[]=[]; const orderNumbers:string[]=[]; let notFoundCount=0,ignoredCount=0;
    // CONFIRM UPLOAD IGNORED ORDER DETAILS
    const recordIgnored=(message:string)=>{ignoredCount++;errors.push('[IGNORED] '+message);};
    const parse=(row:string[])=>row.map(value=>String(value ?? "").trim());
    const lines=matrix.filter(row=>row.some(value=>String(value ?? "").trim()));
    if(lines.length<2)return{entries:[],confirmedCount:0,notFoundCount:0,ignoredCount:0,orderNumbers:[],errors:['CSV has no data rows.']};
    const h=parse(lines[0]).map(v=>v.toLowerCase().trim().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''));
    const idx=(names:string[])=>h.findIndex(x=>names.includes(x));
    const idI=idx(['order_id','order_number','order']);
    const mainI=idx(['main_code','main_sku','product_code']);
    const variantI=idx(['variant_color','variant','color','colour','option']);
    const codeI=idx(['item_code','variant_code','actual_sku','sku']);
    const qtyI=idx(['qty','quantity']);
    const itemStatusI=idx(['item_status','item_action']);
    const decisionI=idx(['decision','call_decision','final_decision','order_action']);
    const callResultI=idx(['call_result','call_status','result']);
    const reasonI=idx(['cancel_reason','reason','notes']);
    const cancelledByI=idx(['cancelled_by','updated_by','call_center_by']);
    const giftWrapI=idx(['gift_wrap','gift_wrapping','wrap']);
    const wrappingCostI=idx(['wrapping_cost_rs','wrapping_cost','gift_wrap_fee','wrapping_fee_rs','wrapping_fee']);
    const applyItemChangeI=idx(['apply_item_change','apply_change']);
    const itemNameI=idx(['item_name','product_name']);
    const unitPriceI=idx(['unit_price_rs','unit_price','price']);
    const lineTotalI=idx(['line_total_rs','line_total']);
    const normalTotalI=idx(['normal_total_rs','normal_total']);
    const offerI=idx(['offer']);
    const discountI=idx(['discount_rs','discount']);
    const deliveryFeeI=idx(['delivery_fee_rs','delivery_fee']);
    const finalTotalI=idx(['final_total_rs','final_total']);
    const addressI=idx(['address','customer_address','delivery_address']);
    const cityI=idx(['city','town','delivery_city']);
    const districtI=idx(['district','delivery_district']);
    const customerNameI=idx(['customer_name','customer','name']);
    if(idI<0||codeI<0||(decisionI<0&&callResultI<0))return{entries:[],confirmedCount:0,notFoundCount:0,ignoredCount:0,orderNumbers:[],errors:['Required columns: Order ID, Item Code, and Order Action (CONFIRM ORDER / CANCEL ENTIRE ORDER). Older Decision/Call Result CSV files are still supported.']};

    const wantedPrefix=source==='Facebook Ads'?'FB':source==='TikTok Ads'?'TK':source==='Website'?'WEB':'';
    const groups=new Map<string,string[][]>();
    lines.slice(1).forEach((line,rowNo)=>{
      const c=parse(line);
      const id=String(c[idI]||'').trim().toUpperCase();
      // DATE / helper / blank rows are not orders, so they must not inflate Ignored.
      if(!id || id.startsWith('DATE:')) return;
      if(wantedPrefix && !id.startsWith(wantedPrefix+'-')){
        recordIgnored('Row '+(rowNo+2)+' • '+id+' • Wrong channel for this upload. FIX: use the ALL CHANNELS Confirm Upload or upload it under '+wantedPrefix+'.');
        return;
      }
      if(!/^(WEB|FB|TK)-\d{6}$/.test(id) && !/^WEB-TEST-\d{3}$/.test(id)){
        recordIgnored('Row '+(rowNo+2)+' • '+id+' • Invalid Order ID format. FIX: use the exact WEB-000000 / FB-000000 / TK-000000 Order ID from the Sheet.');
        return;
      }
      groups.set(id,[...(groups.get(id)||[]),c]);
    });

    const existing=new Map(orders.map(o=>[String(o.order_number||"").toUpperCase(),o] as [string,Order]));
    const now=at; const updates=new Map<string,Partial<Order>>();
    const uploadPackingBatchId=String(packingBatchId || ('PACK-UPLOAD-' + now.replace(/[^0-9]/g,'').slice(0,17)));

    groups.forEach((rows,id)=>{
      const order=existing.get(id); if(!order){notFoundCount++;return;}
      if(source && order.order_source!==source){recordIgnored(id+' • Source mismatch. System source is '+String(order.order_source||'Unknown')+'. FIX: check the Order ID / Source, then upload through ALL CHANNELS.');return;}
      const decisionValues=decisionI>=0?rows.map(c=>String(c[decisionI]||'').trim()).filter(Boolean):[];
      const decisionValue=decisionValues.find(v=>!['pending','blank'].includes(v.toLowerCase().replace(/[_-]+/g,' ').trim())) || decisionValues[0];
      const rawCall=String(decisionValue || (callResultI>=0?rows.map(c=>c[callResultI]).find(v=>String(v||'').trim()):'') || '').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ');
      // Upload is intentionally Confirm + Cancel only. PENDING / NO ANSWER stay in Google Sheet for the next call.
      if(!rawCall || ['pending','blank','no answer','noanswer','reschedule','rescheduled'].includes(rawCall)){recordIgnored(id+' • Order Action is '+(rawCall ? rawCall.toUpperCase() : 'BLANK')+'. FIX: set CONFIRM ORDER or CANCEL ENTIRE ORDER in the Sheet, then upload again.');return;}
      let callResult:Order['call_center_status'];
      if(['confirmed','confirm','confirm order'].includes(rawCall))callResult='Confirmed';else if(['cancelled','canceled','cancel','cancel entire order'].includes(rawCall))callResult='Cancelled';else{errors.push(`${id}: Order Action must be CONFIRM ORDER or CANCEL ENTIRE ORDER. PENDING / NO ANSWER are ignored by upload.`);return;}
      const reason=reasonI>=0?String(rows.map(c=>c[reasonI]).find(Boolean)||'').trim():'';
      if(order.order_status==='Cancelled'){
        recordIgnored(id+' • Order is already Cancelled in O-RA. No action is needed.');
        return;
      }

      if(callResult==='Cancelled'){
        if(order.stock_allocated || order.invoice_locked || ['Shipped','Delivered'].includes(order.order_status)){errors.push(`${id}: This order is already stock/invoice/dispatch locked. Use an Admin correction/return flow instead of Call Center cancellation.`);return;}
        const cancelledBy=cancelledByI>=0?String(rows.map(c=>c[cancelledByI]).find(Boolean)||'Call Center').trim():'Call Center';
        updates.set(id,{call_center_status:'Cancelled',order_status:'Cancelled',call_center_updated_at:now,cancelled_at:now,cancelled_by:cancelledBy,cancel_reason:reason||'Customer/Call Center cancellation',notes:[order.notes,'Cancelled by Call Center',reason?`Reason: ${reason}`:''].filter(Boolean).join(' | ')});orderNumbers.push(id);return;
      }

      if(order.stock_allocated || order.invoice_locked || ['Shipped','Delivered'].includes(order.order_status)){errors.push(`${id}: This order is already stock/invoice/dispatch locked. Qty/Product changes are blocked in Call Center upload.`);return;}
      const itemAction=(c:string[])=>String(c[itemStatusI]||'').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ');
      const isCancelledItem=(c:string[])=>['cancelled','canceled','cancel','cancel item'].includes(itemAction(c));
      const isKeptItem=(c:string[])=>['','confirmed','confirm','pending','keep','keep item'].includes(itemAction(c));
      const confirmed=itemStatusI>=0?rows.filter(c=>!isCancelledItem(c)):rows;
      const cancelled=itemStatusI>=0?rows.filter(c=>isCancelledItem(c)):[];
      const invalid=itemStatusI>=0?rows.filter(c=>!isCancelledItem(c)&&!isKeptItem(c)):[];
      if(invalid.length){errors.push(`${id}: Item Action must be KEEP ITEM or CANCEL ITEM.`);return;}
      if(!confirmed.length){updates.set(id,{call_center_status:'Cancelled',order_status:'Cancelled',call_center_updated_at:now,cancelled_at:now,cancelled_by:'Call Center',cancel_reason:reason||'All items cancelled by Call Center',notes:[order.notes,'All items cancelled by Call Center'].filter(Boolean).join(' | ')});orderNumbers.push(id);return;}

      const nextItems:Order['items']=[]; let bad=false;
      confirmed.forEach((c,rowIndex)=>{
        if(bad)return;
        const actualCode=String(c[codeI]||'').trim().toUpperCase();
        const mainCode=mainI>=0?String(c[mainI]||'').trim().toUpperCase():'';
        const variantValue=variantI>=0?String(c[variantI]||'').trim():'';
        const qty=Math.max(1,Number(qtyI>=0?c[qtyI]:1)||1);
        if(qty>99){errors.push(`${id}: Qty ${qty} is too high.`);bad=true;return;}
        const selection=findProductSelection(products,actualCode||mainCode,variantValue);
        if(!selection){errors.push(`${id}: Item ${actualCode||mainCode} was not found in current Products.`);bad=true;return;}
        if(normalizedProductType(selection.product)==='variant'&&!selection.variant){errors.push(`${id}: Select a Color / Variant for ${selection.product.name_en} on row ${rowIndex+1}.`);bad=true;return;}
        const applyRequested=applyItemChangeI>=0 && ['true','yes','1','on','apply'].includes(String(c[applyItemChangeI]||'').trim().toLowerCase());
        const requestedCode=String(actualCode||mainCode||'').trim().toUpperCase();
        const sameExistingItem=(it:Order['items'][number]|undefined)=>Boolean(it && requestedCode && [String(it.sku||''),String(it.main_sku||'')].map(v=>v.trim().toUpperCase()).includes(requestedCode));
        const indexedExisting=(order.items||[])[rowIndex];
        // The Confirm Sheet's Variant / Color column is authoritative for fulfilment.
        // A same-SKU variant change (for example Twin Tub -> Single Tub in a Combo)
        // must rebuild the item snapshot even when Apply Item Change is FALSE. The old
        // behaviour preserved the original bundle_components and could allocate stock
        // from the old variant while the invoice snapshot showed the new variant.
        const requestedVariant=variantI>=0?String(c[variantI]||'').trim():'';
        const existingCandidate=sameExistingItem(indexedExisting)?indexedExisting:(order.items||[]).find(it=>sameExistingItem(it));
        const existingVariant=String(
          existingCandidate?.variant_name ||
          (existingCandidate?.bundle_components || []).map((component:any)=>String(component?.variant_name||'').trim()).find(Boolean) ||
          ''
        ).trim();
        // A requested Sheet variant is authoritative even when an older combo snapshot
        // did not store a top-level variant_name. Blank old metadata must rebuild too.
        const variantChanged=Boolean(requestedVariant && requestedVariant.toLowerCase()!==existingVariant.toLowerCase());
        const existingItem=!applyRequested && !variantChanged ? existingCandidate : undefined;
        const referenceRaw=unitPriceI>=0?String(c[unitPriceI]||'').trim().replace(/,/g,''):'';
        const referenceMatch=referenceRaw.match(/-?(?:\d+(?:\.\d+)?|\.\d+)/);
        const sheetReferenceUnit=referenceMatch?Math.max(0,Number(referenceMatch[0])||0):0;
        if(existingItem){
          const preservedUnit=Math.max(0,Number(existingItem.unit_price||0));
          const preservedReference=Math.max(
            preservedUnit,
            sheetReferenceUnit,
            Math.max(0,Number((existingItem as any).regular_unit_price||0)),
            preservedUnit+Math.max(0,Number((existingItem as any).supplier_offer_discount_per_unit||0))
          );
          nextItems.push({
            ...existingItem,
            quantity:qty,
            unit_price:preservedUnit,
            subtotal:Math.round(preservedUnit*qty*100)/100,
            regular_unit_price:preservedReference,
            supplier_offer_discount_per_unit:Math.max(0,preservedReference-preservedUnit),
          });
        }else{
          try{
            const freshItem=buildOrderItemSnapshot(selection.product,qty,settings,selection.variant,products);
            if(normalizedProductType(selection.product)==='bundle' && requestedVariant) freshItem.variant_name=requestedVariant;
            const freshUnit=Math.max(0,Number(freshItem.unit_price||0));
            const freshMain=String(freshItem.main_sku||selection.product.sku||mainCode||'').trim().toUpperCase();
            // Same main product must keep the order's locked unit price even when
            // Call Center explicitly applies a color/variant change. A color split
            // must never turn one historical Rs.X item into a different catalog price.
            const historicalSibling=(order.items||[]).find(it=>{
              const siblingMain=String(it.main_sku||it.sku||'').trim().toUpperCase();
              return Boolean(freshMain && siblingMain===freshMain);
            });
            if(historicalSibling){
              const historicalActual=Math.max(0,Number(historicalSibling.unit_price||0)) || freshUnit;
              const historicalReference=Math.max(
                historicalActual,
                sheetReferenceUnit,
                Number(historicalSibling.regular_unit_price||0),
                historicalActual+Number(historicalSibling.supplier_offer_discount_per_unit||0)
              );
              nextItems.push({
                ...freshItem,
                unit_price:historicalActual,
                subtotal:Math.round(historicalActual*qty*100)/100,
                regular_unit_price:historicalReference,
                supplier_offer_discount_per_unit:Math.max(0,Math.round((historicalReference-historicalActual)*100)/100),
              });
            }else{
              const referenceUnit=Math.max(
                freshUnit,
                sheetReferenceUnit,
                Math.max(0,Number((freshItem as any).regular_unit_price||0)),
                freshUnit+Math.max(0,Number((freshItem as any).supplier_offer_discount_per_unit||0))
              );
              nextItems.push({
                ...freshItem,
                regular_unit_price:referenceUnit,
                supplier_offer_discount_per_unit:Math.max(0,referenceUnit-freshUnit),
              });
            }
          }catch(e:any){errors.push(id + ': ' + (e?.message||'Invalid item selection.'));bad=true;}
        }
      });
      if(bad)return;
      const giftWrapRaw=giftWrapI>=0?String(rows.map(c=>c[giftWrapI]).find(v=>String(v||'').trim())||'').trim():'';
      const gift_wrap_selected=giftWrapRaw
        ? ['yes','true','1','on','add wrap','gift wrap'].includes(giftWrapRaw.toLowerCase())
        : Boolean(order.gift_wrap_selected);
      const sheetWrappingCost=wrappingCostI>=0?Number(String(rows.map(c=>c[wrappingCostI]).find(v=>String(v||'').trim())||0).replace(/[^0-9.-]/g,'')):0;
      const gift_wrap_fee=gift_wrap_selected
        ? Math.max(0,Number(sheetWrappingCost || order.gift_wrap_fee || settings.gift_wrap_fee || 0))
        : 0;
      const totalQty=nextItems.reduce((n,it)=>n+it.quantity,0);
      const subtotal=nextItems.reduce((n,it)=>n+it.subtotal,0);
      const rate=getMultiBuyDiscountRate(totalQty);
      const useDeliveryQtyOffer=order.delivery_rebalance_qty_offer===true || Number(order.delivery_rebalance_amount_snapshot||0)>0;
      const confirmRebalanceAmount=useDeliveryQtyOffer
        ? Math.max(0,Number(order.delivery_rebalance_amount_snapshot ?? settings.delivery_price_rebalance_amount ?? 0))
        : 0;
      const legacySubtotal=Math.max(0,subtotal-confirmRebalanceAmount*totalQty);
      const special_offer_discount=useDeliveryQtyOffer
        ? Math.round(legacySubtotal*(rate/100)*100)/100
        : Math.max(0,Number(order.special_offer_discount||0));
      const delivery_rebalance_qty_offer_amount=useDeliveryQtyOffer
        ? Math.round(confirmRebalanceAmount*Math.max(0,totalQty-1)*100)/100
        : Math.max(0,Number(order.delivery_rebalance_qty_offer_amount||0));
      const delivery_fee=useDeliveryQtyOffer
        ? (settings.free_delivery_enabled?0:Math.max(0,Number(order.delivery_visible_fee_snapshot ?? settings.delivery_fee ?? 0)))
        : Math.max(0,Number(order.delivery_fee||0));
      const total_amount=Math.round(Math.max(0,subtotal-special_offer_discount-delivery_rebalance_qty_offer_amount+delivery_fee+gift_wrap_fee));
      const threshold=Math.max(0,Number(settings.advance_qty_threshold??4)),adv=totalQty>threshold,pct=Math.min(100,Math.max(1,Number(settings.advance_percentage??50)));
      const confirmedAddress=addressI>=0?String(rows.map(c=>c[addressI]).find(v=>String(v||'').trim())||'').trim():'';
      const confirmedCity=cityI>=0?String(rows.map(c=>c[cityI]).find(v=>String(v||'').trim())||'').trim():'';
      const confirmedDistrict=districtI>=0?String(rows.map(c=>c[districtI]).find(v=>String(v||'').trim())||'').trim():'';
      const cityChanged=Boolean(confirmedCity && confirmedCity.trim().toLowerCase()!==String(order.city||'').trim().toLowerCase());
      const oldShape=(order.items||[]).map(it=>({sku:it.sku,product_name:it.product_name,variant_name:it.variant_name,quantity:it.quantity,unit_price:it.unit_price}));
      const newShape=nextItems.map(it=>({sku:it.sku,product_name:it.product_name,variant_name:it.variant_name,quantity:it.quantity,unit_price:it.unit_price}));
      const changed=JSON.stringify(oldShape)!==JSON.stringify(newShape);
      // If item rows/qty changed, recalculate the order-level multi-buy offer
      // from the preserved item prices. Variant/color splitting must keep identical
      // unit prices; the quantity offer belongs here, never inside one item's price.
      const recalculatedQtyOfferDiscount=Math.round(legacySubtotal*(rate/100)*100)/100;
      const stableQtyOfferDiscount=changed?recalculatedQtyOfferDiscount:Math.max(0,Number(order.special_offer_discount||0));
      const stableDeliveryQtyOffer=changed?delivery_rebalance_qty_offer_amount:Math.max(0,Number(order.delivery_rebalance_qty_offer_amount||0));
      const stableTotalAmount=Math.round(Math.max(0,subtotal-stableQtyOfferDiscount-stableDeliveryQtyOffer+delivery_fee+gift_wrap_fee));
      const parseConfirmedMoney=(value:any)=>{
        if(typeof value==='number') return Number.isFinite(value)?value:0;
        const raw=String(value ?? '').trim().replace(/,/g,'');
        const match=raw.match(/-?(?:\d+(?:\.\d+)?|\.\d+)/);
        const n=match?Number(match[0]):0;
        return Number.isFinite(n)?n:0;
      };
      const csvMoney=(col:number)=>col>=0?parseConfirmedMoney(rows.map(c=>c[col]).find(v=>String(v||'').trim())):0;
      const csvText=(col:number)=>col>=0?String(rows.map(c=>c[col]).find(v=>String(v||'').trim())||'').trim():'';
      const sheetCity=csvText(cityI) || order.city;
      const sheetDistrict=csvText(districtI) || String(order.district||'');
      const sheetCustomerName=csvText(customerNameI) || String(order.customer_name||'');
      const rawCsvFinalTotal=csvMoney(finalTotalI);
      const rawCsvNormalTotal=csvMoney(normalTotalI);
      const rawCsvDiscount=csvMoney(discountI);
      const rawCsvDelivery=csvMoney(deliveryFeeI);
      const csvNoWrapTotal=Math.round(Math.max(0,rawCsvNormalTotal-rawCsvDiscount+rawCsvDelivery));
      const csvWithWrapTotal=Math.round(Math.max(0,csvNoWrapTotal+(gift_wrap_selected?gift_wrap_fee:0)));
      const csvFormulaAvailable=rawCsvNormalTotal>0;
      const safeInvoiceFinalTotal=csvFormulaAvailable?csvWithWrapTotal:(rawCsvFinalTotal||stableTotalAmount);
      const invoiceConfirmSnapshot={
        captured_at:now,
        city:sheetCity,
        district:sheetDistrict,
        normal_total:csvMoney(normalTotalI),
        offer:csvText(offerI),
        discount:csvMoney(discountI),
        delivery_fee:csvMoney(deliveryFeeI),
        gift_wrap:giftWrapRaw,
        wrapping_cost:sheetWrappingCost,
        final_total:safeInvoiceFinalTotal,
        items:confirmed.map(c=>({
          item_code:String(c[codeI]||'').trim(),
          item_name:itemNameI>=0?String(c[itemNameI]||'').trim():'',
          variant:variantI>=0?String(c[variantI]||'').trim():'',
          qty:Math.max(1,Number(qtyI>=0?c[qtyI]:1)||1),
          unit_price:unitPriceI>=0?parseConfirmedMoney(c[unitPriceI]):0,
          line_total:lineTotalI>=0?parseConfirmedMoney(c[lineTotalI]):0,
          item_action:itemStatusI>=0?String(c[itemStatusI]||'').trim():''
        }))
      };

      updates.set(id,{items:nextItems,subtotal,special_offer_discount:stableQtyOfferDiscount,delivery_rebalance_qty_offer:useDeliveryQtyOffer,delivery_rebalance_qty_offer_amount:stableDeliveryQtyOffer,delivery_rebalance_amount_snapshot:order.delivery_rebalance_amount_snapshot,delivery_visible_fee_snapshot:order.delivery_visible_fee_snapshot,delivery_fee,gift_wrap_selected,gift_wrap_fee,total_amount:stableTotalAmount,is_advance_required:adv,advance_amount:adv?Math.round(stableTotalAmount*pct/100):0,...(confirmedAddress?{address:confirmedAddress}:{}),customer_name:sheetCustomerName,city:sheetCity,district:sheetDistrict,...(cityChanged?{fardar_city:undefined,city_verified:false,city_mapping_source:undefined}:{}),confirm_upload_batch_id:uploadPackingBatchId,invoice_confirm_snapshot:invoiceConfirmSnapshot,...(paymentMode==='full_paid'?{payment_method:'Bank Payment' as PaymentMethod,payment_status:'Paid' as const,payment_paid_type:'Full' as const,payment_received_amount:stableTotalAmount,payment_verification_status:'Approved' as const,payment_reviewed_at:now,payment_reviewed_by:'Full Payment Upload',is_advance_required:false,advance_amount:0,advance_confirmed:false,invoice_payment_label_snapshot:'FULLY PAID'}:paymentMode==='advance_50'?{payment_method:'COD' as PaymentMethod,payment_status:'Pending' as const,payment_paid_type:'Advance' as const,payment_received_amount:Math.round(stableTotalAmount*0.5),payment_verification_status:'Approved' as const,payment_reviewed_at:now,payment_reviewed_by:'50% Advance Upload',is_advance_required:true,advance_amount:Math.round(stableTotalAmount*0.5),advance_confirmed:true,invoice_payment_label_snapshot:'50% ADVANCE PAID'}:{}),call_center_status:'Confirmed',order_status:'Processing',call_center_updated_at:now,stock_allocated:false,stock_status:'Waiting for Stock',product_change_history:changed?[...(order.product_change_history||[]),{changed_at:now,changed_by:'Call Center Confirm Upload',old_items:oldShape,new_items:newShape,reason:reason||undefined}]:(order.product_change_history||[]),notes:[order.notes,cancelled.length?`Call Center cancelled ${cancelled.length} item row(s).`:'',reason?`Call Center: ${reason}`:''].filter(Boolean).join(' | ')});
      orderNumbers.push(id);
    });

    // Persist every Confirm/Cancel decision BEFORE changing the browser state.
    // Previously these writes were fire-and-forget, so a failed/late server write
    // could be overwritten by the next authoritative server refresh.
    const entries=[];
    for(const [orderNumber,patch] of updates.entries()){
      const original=existing.get(orderNumber);
      if(!original) continue;
      entries.push({id:String(original.id),order_number:orderNumber,expected:canonicalJson(original),patch,
        clear_fields:['fardar_city','city_mapping_source'].filter(field=>Object.hasOwn(patch,field)&&(patch as any)[field]===undefined)});
    }
    return {entries:entries as ConfirmCsvEntry[],errors,orderNumbers,notFoundCount,ignoredCount};
}
